styles.h1:
font-family: "Comic Sans MS", "Ma Shan Zheng", "PingFang SC", cursive;
font-size: 28px;
position: relative;
color: #5e7cff;
margin-bottom: 15px;
letter-spacing: 1px;
font-weight: 600;
text-align: center;
padding: 5px 0;
text-shadow: 1px 1px 2px rgba(165, 199, 254, 0.5);

styles.h2:
font-size: 18px;
color: #7a6cb0;
margin-bottom: 20px;
font-weight: 500;
letter-spacing: 0.5px;
text-align: center;
position: relative;
padding-bottom: 15px;
font-family: "Comic Sans MS", "PingFang SC", sans-serif;

styles.h3:
display: block;
color: #5e7cff;
margin-bottom: 6px;
font-size: 17px;
font-weight: 600;
font-family: "Comic Sans MS", "PingFang SC", sans-serif;

styles.h6:
color: #6b8c42;
margin-top: 1.2em;
margin-bottom: 0.5em;
font-weight: 700;
border-bottom: 1px solid #d4d9c9;
padding-bottom: 0.3em;

styles.a:
color: #7a6cb0;
text-decoration: none;
border-bottom: 1px dashed #a5c7fe;
transition: all 0.3s ease;

styles.ol:
list-style: none;
padding: 0.5em 3.5em;
counter-reset: decorated-counter;
margin-bottom: 1.5em;

styles.li:
position: relative;


margin-bottom: 20px;
padding-left: 36px;
color: #555;
font-size: 16px;
font-family: "Comic Sans MS", "PingFang SC", sans-serif;

styles.blockquote:
background-color: rgba(248, 240, 255, 0.7);
border-left: 4px solid #ffb7c5;
color: #7a6cb0;
padding: 15px 20px;
margin: 20px 0;
border-radius: 0 10px 10px 0;
font-style: italic;

styles.pre:
border: 2px dashed #a5c7fe;
box-shadow: 0 4px 15px rgba(165, 199, 254, 0.1);
background-color: rgba(248, 240, 255, 0.7);
border-radius: 10px;
padding: 15px;
overflow-x: auto;

styles.hr:
height: 3px;
border: none;
background: repeating-linear-gradient(
  90deg,
  #ffb7c5,
  #ffb7c5 10px,
  #a5c7fe 10px,
  #a5c7fe 20px
);
border-radius: 3px;
margin: 25px 0;

styles.img:
border: 3px solid white;
box-shadow: 0 5px 15px rgba(165, 199, 254, 0.3);
border-radius: 15px;
max-width: 100%;
height: auto;
margin: 15px 0;
transition: transform 0.3s ease;

styles.table:
box-shadow: 0 4px 15px rgba(165, 199, 254, 0.2);
border-radius: 10px;
overflow: hidden;
border-collapse: collapse;
margin: 20px 0;
border: 2px dashed #a5c7fe;

styles.th:
background-color: rgba(165, 199, 254, 0.2);
color: #5e7cff;
padding: 10px 15px;
text-align: left;
border-bottom: 2px dashed #a5c7fe;
